package com.almaraama.shared.id;

import java.util.Objects;
import java.util.UUID;

/** Public identifier of an organization (sites module), referenced by other modules (CF-2, CF-10). */
public record OrganizationId(UUID value) {

    public OrganizationId {
        Objects.requireNonNull(value, "value");
    }

    /** A new UUID v7 identifier, generated by the application (CF-10). */
    public static OrganizationId newId() {
        return new OrganizationId(UuidV7.next());
    }

    /** The UUID in its canonical text form. */
    @Override
    public String toString() {
        return value.toString();
    }
}
